const np=Math.round(30+P.density*80);
const rise=(0.05+P.speed*0.06);
const turb=(0.3+P.turb*1.1);
// rising vapor puffs: buoyant sway + slow curl advection, grow+fade as they rise
for(let k=0;k<np;k++){ const pf=S.pf[k];
  const life=(pf[1] + t*rise*(0.6+pf[2]))%1;
  const sway= turb*0.10*Math.sin(t*(0.6+pf[2]) + pf[0]*6.28) + 0.06*vn(pf[0]*4 + t*0.2, life*5)*turb;
  const spreadX=(pf[0]-0.5)*0.16*(0.4+life);
  const X=(srcx + spreadX + sway)*width;
